<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $seed = json_decode(file_get_contents(__DIR__."/../scratch_seed.json"), true); foreach($seed["risks"] as $r) { if(empty($r["linkedActionIds"])) continue; $riesgo = Illuminate\Support\Facades\DB::table("riesgos")->where("local_id", $r["id"])->first(); if(!$riesgo) continue; foreach($r["linkedActionIds"] as $actIdStr) { $poaAct = null; foreach($seed["poaActions"] as $pa) { if($pa["id"] === $actIdStr) { $poaAct = $pa; break; } } if(!$poaAct) continue; $dbAct = Illuminate\Support\Facades\DB::table("acciones_sustantivas")->join("proyectos", "acciones_sustantivas.proyecto_id", "=", "proyectos.proyecto_id")->where("proyectos.ejercicio_id", 2026)->where("acciones_sustantivas.descripcion", "like", "%".trim($poaAct["text"])."%")->select("acciones_sustantivas.accion_sustantiva_id")->first(); if(!$dbAct) { $dbAct = Illuminate\Support\Facades\DB::table("actividades_sustantivas")->join("proyectos", "actividades_sustantivas.proyecto_id", "=", "proyectos.proyecto_id")->where("proyectos.ejercicio_id", 2026)->where("actividades_sustantivas.descripcion", "like", "%".trim($poaAct["text"])."%")->select("actividades_sustantivas.id as accion_sustantiva_id")->first(); } if($dbAct) { $actId = $dbAct->accion_sustantiva_id; Illuminate\Support\Facades\DB::table("actividad_riesgo")->updateOrInsert(["actividad_sustantiva_id" => $actId, "riesgo_id" => $riesgo->id]); echo "Linked ".$riesgo->local_id." to action ID: $actId\n"; } else { echo "Not found action for text: " . $poaAct["text"] . "\n"; } } }
